<?php
declare(strict_types=1);
require __DIR__.'/../server/Leaderboard.php';
use StarRebound\Leaderboard; use StarRebound\ApiError;
// Real in-memory SQLite, with only the observed unsupported grammar rejected.
// This is a local regression guard, not an emulation of all SQLite 3.7.17 behavior.
class NoUpsertPDO extends PDO {
 public function __construct(){parent::__construct('sqlite::memory:');}
 public function prepare(string $query,array $options=[]):PDOStatement|false {
  if(preg_match('/ON\s+CONFLICT\s*\(.*?\)\s+DO\s+UPDATE/is',$query))throw new PDOException('legacy SQLite: near ON syntax error');
  return parent::prepare($query,$options);
 }
}
$clock=1000.0;$results=[];
function check($ok,$message){if(!$ok)throw new RuntimeException($message);}
function test($name,$fn){global $results;try{$fn();$results[]=['name'=>$name,'status'=>'PASS'];}catch(Throwable $e){$results[]=['name'=>$name,'status'=>'FAIL','message'=>$e->getMessage()];}}
function fixture(){ $db=new NoUpsertPDO();return [$db,new Leaderboard($db,fn()=>$GLOBALS['clock'])]; }
function resultFor($store,$points=120){$r=$store->start('synthetic','nightmare');$GLOBALS['clock']+=10;return ['runId'=>$r['runId'],'nonce'=>$r['nonce'],'difficulty'=>$r['difficulty'],'ruleset'=>$r['ruleset'],'seed'=>$r['seed'],'name'=>'合成星','score'=>$points,'time'=>8.0,'result'=>'lost','stageIndex'=>0,'completedStages'=>0,'hp'=>0,'kills'=>1,'returned'=>0,'bestCombo'=>1,'hits'=>2,'captureUses'=>0,'details'=>['version'=>1,'heals'=>0,'scoreBreakdown'=>['defeats'=>$points,'returns'=>0,'lifeBonus'=>0]]];}
test('start finish retry and improved best preserve score row identity and matching details',function(){[$db,$s]=fixture();$p=resultFor($s);$first=$s->finish('synthetic',$p);check($first===$s->finish('synthetic',$p),'retry changed');$id=$db->query('SELECT id FROM scores')->fetchColumn();$higher=$s->finish('synthetic',resultFor($s,240));check($higher['improved']&&$higher['entry']['score']===240,'higher best lost');check($db->query('SELECT id FROM scores')->fetchColumn()===$id,'row ID changed');check($higher['entry']['details']['scoreBreakdown']['defeats']===240,'detail stale');foreach([240,120]as $score){$r=$s->finish('synthetic',resultFor($s,$score));check(!$r['improved']&&$r['entry']===$higher['entry'],'equal/lower replaced best');}check($s->top('nightmare')['entries'][0]===$higher['entry'],'top changed');});
test('rate bucket increments without resetting expiry and rejected start rolls back',function(){[$db,$s]=fixture();$s->start('limited','nightmare');$expiry=$db->query('SELECT expires FROM rates')->fetchColumn();for($i=1;$i<30;$i++){$GLOBALS['clock']+=1;$s->start('limited','nightmare');}check($db->query('SELECT expires FROM rates')->fetchColumn()===$expiry,'existing expiry changed');$before=$db->query('SELECT * FROM rates')->fetchAll();try{$s->start('limited','nightmare');throw new RuntimeException('rate limit missing');}catch(ApiError $e){check($e->status===429,'wrong status');}check($db->query('SELECT * FROM rates')->fetchAll()===$before,'rejected count did not roll back');check((int)$before[0]['count']===30,'count reset');});
test('detail update failure rolls back improved score run and rate then exact retry succeeds',function(){[$db,$s]=fixture();$s->finish('synthetic',resultFor($s));$p=resultFor($s,240);$before=$db->query('SELECT * FROM scores')->fetchAll();$details=$db->query('SELECT * FROM score_details')->fetchAll();$rates=$db->query('SELECT * FROM rates')->fetchAll();$db->exec("CREATE TRIGGER fail_update BEFORE UPDATE ON score_details BEGIN SELECT RAISE(ABORT,'synthetic update failure'); END");try{$s->finish('synthetic',$p);throw new RuntimeException('injected failure missing');}catch(PDOException $e){}check($db->query('SELECT * FROM scores')->fetchAll()===$before,'score update escaped');check($db->query('SELECT * FROM score_details')->fetchAll()===$details,'detail changed');check($db->query('SELECT * FROM rates')->fetchAll()===$rates,'rate update escaped');$q=$db->prepare('SELECT response FROM runs WHERE id=?');$q->execute([$p['runId']]);check($q->fetchColumn()===null,'run response escaped');$db->exec('DROP TRIGGER fail_update');check($s->finish('synthetic',$p)['entry']['score']===240,'retry failed');});
test('updating a legacy best without metadata retains its ID and creates details',function(){[$db,$s]=fixture();$q=$db->prepare('INSERT INTO scores(id,browser,difficulty,ruleset,name,score,stage,cleared,recorded) VALUES(41,?,?,?,?,0,0,0,1)');$q->execute(['synthetic','nightmare',Leaderboard::RULESET,'旧星']);$r=$s->finish('synthetic',resultFor($s));check((int)$db->query('SELECT id FROM scores')->fetchColumn()===41,'legacy ID replaced');check($r['entry']['details']['kills']===1,'metadata not inserted');check((int)$db->query('PRAGMA user_version')->fetchColumn()===1,'schema changed');});
$failed=count(array_filter($results,fn($r)=>$r['status']==='FAIL'));echo json_encode(['failed'=>$failed,'results'=>$results],JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT);exit($failed?1:0);
